<div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-4"><div><h1 class="h3 mb-1">Profissionais</h1><p class="text-secondary mb-0">Cadastre a equipe, crie acessos individuais e configure disponibilidade.</p></div></div>
<div class="card mb-4"><div class="card-body"><form method="post" action="/professionals" class="row g-3"><?php echo \App\Core\CSRF::field();?><div class="col-md-3"><label class="form-label">Nome</label><input class="form-control" name="name" required></div><div class="col-md-3"><label class="form-label">E-mail</label><input class="form-control" type="email" name="email"></div><div class="col-md-2"><label class="form-label">Telefone</label><input class="form-control" name="phone"></div><div class="col-md-2"><label class="form-label">Especialidade</label><input class="form-control" name="specialty"></div><?php if($multiunitEnabled):?><div class="col-md-2"><label class="form-label">Unidade</label><select class="form-select" name="unit_id"><option value="">Sem unidade</option><?php foreach($units as $u):?><option value="<?=(int)$u['id']?>"><?=htmlspecialchars($u['name'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></div><?php endif;?><div class="col-md-2"><label class="form-label">Comissão %</label><input class="form-control" type="number" step=".01" min="0" max="100" name="commission_percent"></div><div class="col-12"><label class="form-check"><input class="form-check-input" type="checkbox" name="create_access" value="1"> Criar acesso individual por e-mail</label><small class="text-secondary">O sistema gerará uma senha temporária de 6 dígitos, exibida uma única vez. O profissional deverá alterá-la no primeiro acesso.</small></div><div><button class="btn btn-primary">Cadastrar profissional</button></div></form></div></div>
<div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Profissional</th><th>Especialidade</th><?php if($multiunitEnabled):?><th>Unidade</th><?php endif;?><th>Acesso</th><th>Link público</th><th class="text-end">Ações</th></tr></thead><tbody><?php foreach($professionals as $p):$shareUrl=$publicBase.'/a/'.$tenantSlug.'/p/'.($p['public_slug']??'');?><tr><td><strong><?=htmlspecialchars($p['name'],ENT_QUOTES,'UTF-8')?></strong><?php if(!$p['active']):?><span class="badge text-bg-secondary ms-1">Inativo</span><?php endif;?></td><td><?=htmlspecialchars($p['specialty']??'—',ENT_QUOTES,'UTF-8')?></td><?php if($multiunitEnabled):?><td><?=htmlspecialchars($p['unit_name']??'—',ENT_QUOTES,'UTF-8')?></td><?php endif;?><td><?=$p['user_id']?'<span class="badge text-bg-light">'.htmlspecialchars($p['user_status']??'').'</span>':'Sem acesso'?></td><td><?php if($tenantSlug&&$p['public_slug']):?><div class="d-flex flex-wrap gap-1"><a class="btn btn-sm btn-outline-primary" href="/a/<?=htmlspecialchars($tenantSlug,ENT_QUOTES,'UTF-8')?>/p/<?=htmlspecialchars($p['public_slug'],ENT_QUOTES,'UTF-8')?>" target="_blank" rel="noopener">Abrir</a><button class="btn btn-sm btn-primary" type="button" data-native-share data-share-url="<?=htmlspecialchars($shareUrl,ENT_QUOTES,'UTF-8')?>" data-share-title="Agende com <?=htmlspecialchars($p['name'],ENT_QUOTES,'UTF-8')?>" data-share-text="Veja os horários disponíveis e faça seu agendamento.">Compartilhar</button></div><?php else:?>—<?php endif;?></td><td class="text-end"><?php if(!empty($barberMode)&&\App\Core\Authorization::allows('barber.compensation.manage')):?><a class="btn btn-sm btn-outline-secondary" href="/barber/team/<?=(int)$p['id']?>">Modelo / comissão</a> <?php endif;?><a class="btn btn-sm btn-outline-primary" href="/professionals/<?=(int)$p['id']?>/edit">Editar</a><form class="d-inline" method="post" action="/professionals/<?=(int)$p['id']?>/delete" onsubmit="return confirm('Inativar este profissional? O histórico será preservado.');"><?php echo \App\Core\CSRF::field();?><button class="btn btn-sm btn-outline-danger">Excluir</button></form></td></tr><?php endforeach;?><?php if(!$professionals):?><tr><td colspan="<?=$multiunitEnabled?6:5?>"><div class="empty-state">Nenhum profissional cadastrado.</div></td></tr><?php endif;?></tbody></table></div></div>
